module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
// Define parameters for states
parameter IDLE = 3'b000;
parameter PULSE_START = 3'b001;
parameter PULSE_END = 3'b010;
// Declare state register
reg [2:0] state;
// Declare next state logic
reg [2:0] next_state;
// Sequential logic for state updates
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end
// Combinational logic for next state determination
always @(*) begin
    case (state)
        IDLE: begin
            if (data_in == 1'b1) 
                next_state = PULSE_START;
            else 
                next_state = IDLE;
        end
        PULSE_START: begin
            if (data_in == 1'b0) 
                next_state = PULSE_END;
            else 
                next_state = PULSE_START;
        end
        PULSE_END: begin
            if (data_in == 1'b1) 
                next_state = PULSE_START;
            else 
                next_state = IDLE;
        end
        default: next_state = IDLE;
    endcase
end
// Combinational logic for output generation
always @(*) begin
    case (state)
        PULSE_END: begin
            if (data_in == 1'b0) 
                data_out = 1'b1;
            else 
                data_out = 1'b0;
        end
        default: data_out = 1'b0;
    endcase
end
endmodule
